<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Global Food Waste Supply Chain Analysis</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&family=JetBrains+Mono:wght@400;500;600&display=swap" rel="stylesheet">
  <script src="/app/libs/chart.js"></script>
  <style>
    :root {
      --bg: #faf9f7;
      --surface: #ffffff;
      --border: rgba(0,0,0,0.08);
      --text: #1a1a1a;
      --text-dim: #6b6b6b;
      --accent-warm: #c2410c;
      --accent-warm-dim: rgba(194,65,12,0.12);
      --accent-teal: #0d9488;
      --accent-teal-dim: rgba(13,148,136,0.12);
      --accent-amber: #d97706;
      --accent-amber-dim: rgba(217,119,6,0.12);
      --accent-slate: #334155;
      --stage-production: #1e3a5f;
      --stage-processing: #0891b2;
      --stage-retail: #d97706;
      --stage-consumption: #be123c;
      --font-serif: 'Instrument Serif', Georgia, serif;
      --font-mono: 'JetBrains Mono', monospace;
    }

    @media (prefers-color-scheme: dark) {
      :root {
        --bg: #0f1117;
        --surface: #1a1d27;
        --border: rgba(255,255,255,0.08);
        --text: #f0f0f0;
        --text-dim: #9ca3af;
      }
    }

    * { box-sizing: border-box; margin: 0; padding: 0; }

    body {
      font-family: var(--font-mono);
      background: var(--bg);
      color: var(--text);
      line-height: 1.5;
      padding: 40px;
    }

    .page {
      max-width: 1200px;
      margin: 0 auto;
      display: grid;
      gap: 32px;
    }

    header {
      text-align: center;
      padding-bottom: 24px;
      border-bottom: 1px solid var(--border);
    }

    header h1 {
      font-family: var(--font-serif);
      font-size: 2.4rem;
      font-weight: 400;
      letter-spacing: -0.02em;
      margin-bottom: 8px;
    }

    header .subtitle {
      font-size: 0.85rem;
      color: var(--text-dim);
      text-transform: uppercase;
      letter-spacing: 0.1em;
    }

