  <div class="page">
    <header>
      <h1>Global Food Waste Supply Chain</h1>
      <p class="subtitle">Waste distribution, carbon emissions & intervention potential by stage</p>
    </header>

    <div class="chart-grid">
      <div class="chart-card hero">
        <h2>Waste Share vs. Carbon Emissions by Stage</h2>
        <p class="desc">Comparing food waste volume distribution with associated carbon emission contributions reveals disproportionate impact</p>

        <div class="legend-inline">
          <div class="legend-item"><span class="legend-dot waste"></span> Waste Share (%)</div>
          <div class="legend-item"><span class="legend-dot carbon"></span> Carbon Emission Share (%)</div>
          <div class="legend-item"><span class="legend-dot avoidable"></span> Avoidable Waste (%)</div>
        </div>

        <div class="chart-container tall">
          <canvas id="mainChart"></canvas>
        </div>

        <div class="insight-callout">
          <span class="icon">⚡</span>
          <p><strong>Production &amp; Processing</strong> have disproportionate carbon intensity — they account for only 42% of waste but <strong>52.5% of emissions</strong>. Consumption dominates waste (43%) but has relatively lower carbon intensity per unit.</p>
        </div>
      </div>

      <div class="chart-card">
        <h2>Intervention Priority Matrix</h2>
        <p class="desc">Potential food savings vs. carbon avoidance by stage</p>
        <div class="chart-container">
          <canvas id="interventionChart"></canvas>
        </div>
      </div>

      <div class="chart-card">
        <h2>Waste Distribution by Region</h2>
        <p class="desc">Supply chain hotspots shift from production (developing) to consumption (developed)</p>
        <div class="chart-container">
          <canvas id="regionalChart"></canvas>
        </div>
      </div>

      <div class="chart-card">
        <h2>Carbon Emissions by Stage</h2>
        <p class="desc">Absolute emissions in Mt CO2e with percentage contribution</p>
        <div class="chart-container">
          <canvas id="emissionsChart"></canvas>
        </div>
      </div>

      <div class="chart-card">
        <h2>Avoidable Waste by Region &amp; Stage</h2>
        <p class="desc">Technically avoidable proportion highlights intervention opportunities</p>
        <div class="chart-container">
          <canvas id="avoidableChart"></canvas>
        </div>
      </div>
    </div>

    <footer>
      Data: FAO/UNEP 2021–2023 &bull; Values in percent unless noted &bull; Mt = megatonnes
    </footer>
  </div>

  <script>
    const isDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
    const textColor = isDark ? '#e5e5e5' : '#1a1a1a';
    const textDim = isDark ? '#9ca3af' : '#6b6b6b';
    const gridColor = isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.06)';
    const surface = isDark ? '#1a1d27' : '#ffffff';

    const stages = ['Production', 'Processing', 'Retail', 'Consumption'];
    const stageColors = {
      Production: isDark ? '#60a5fa' : '#1e3a5f',
      Processing: isDark ? '#22d3ee' : '#0891b2',
      Retail: isDark ? '#fbbf24' : '#d97706',
      Consumption: isDark ? '#fb7185' : '#be123c'
    };

    // Main chart: Waste vs Carbon
    const wasteData = [24.0, 18.0, 15.0, 43.0];
    const carbonData = [30.5, 22.0, 16.5, 31.0];
    const avoidableData = [65, 67, 64, 52];

    new Chart(document.getElementById('mainChart'), {
      type: 'bar',
      data: {
        labels: stages,
        datasets: [
          {
            label: 'Waste Share (%)',
            data: wasteData,
            backgroundColor: Object.values(stageColors),
            borderRadius: 4,
            borderSkipped: false,
          },
          {
            label: 'Carbon Emission Share (%)',
            data: carbonData,
            backgroundColor: isDark ? 'rgba(251,191,36,0.6)' : 'rgba(217,119,6,0.5)',
            borderRadius: 4,
            borderSkipped: false,
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            display: false
          },
          tooltip: {
            callbacks: {
              afterBody: function(context) {
                const idx = context[0].dataIndex;
                return `Avoidable: ${avoidableData[idx]}%`;
              }
            }
          }
        },
        scales: {
          x: {
            ticks: { color: textDim, font: { family: 'JetBrains Mono', size: 11 } },
            grid: { color: gridColor }
          },
          y: {
            ticks: { color: textDim, font: { family: 'JetBrains Mono', size: 11 }, callback: v => v + '%' },
            grid: { color: gridColor },
            max: 50
          }
        }
      }
    });

    // Intervention chart: Food saved vs CO2 avoided (bubble-like bar)
    new Chart(document.getElementById('interventionChart'), {
      type: 'bar',
      data: {
        labels: stages,
        datasets: [
          {
            label: 'Food Saved (Mt)',
            data: [210, 155, 120, 280],
            backgroundColor: isDark ? 'rgba(34,197,94,0.7)' : 'rgba(22,163,74,0.6)',
            borderRadius: 4,
            borderSkipped: false,
          },
          {
            label: 'CO₂ Avoided (Mt)',
            data: [890, 665, 475, 725],
            backgroundColor: isDark ? 'rgba(34,211,238,0.6)' : 'rgba(8,145,178,0.5)',
            borderRadius: 4,
            borderSkipped: false,
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { labels: { color: textDim, font: { family: 'JetBrains Mono', size: 10 } } }
        },
        scales: {
          x: { ticks: { color: textDim, font: { family: 'JetBrains Mono', size: 11 } }, grid: { color: gridColor } },
          y: { ticks: { color: textDim, font: { family: 'JetBrains Mono', size: 11 }, callback: v => v + ' Mt' }, grid: { color: gridColor } }
        }
      }
    });

    // Regional stacked comparison
    const regions = ['North America & Oceania', 'Europe', 'Sub-Saharan Africa', 'South & Southeast Asia', 'Latin America', 'Global Average'];
    const regionColors = {
      'North America & Oceania': isDark ? '#818cf8' : '#6366f1',
      'Europe': isDark ? '#22d3ee' : '#0891b2',
      'Sub-Saharan Africa': isDark ? '#86efac' : '#65a30d',
      'South & Southeast Asia': isDark ? '#fbbf24' : '#d97706',
      'Latin America': isDark ? '#f87171' : '#c2410c',
      'Global Average': isDark ? '#9ca3af' : '#6b6b6b'
    };

    const regionalWaste = {
      'Production': [12.0, 14.0, 39.0, 32.0, 28.0, 24.0],
      'Processing': [8.5, 10.0, 28.0, 24.0, 19.0, 18.0],
      'Retail': [11.0, 12.5, 19.0, 18.0, 17.0, 15.0],
      'Consumption': [68.5, 63.5, 14.0, 26.0, 36.0, 43.0]
    };

    new Chart(document.getElementById('regionalChart'), {
      type: 'bar',
      data: {
        labels: stages,
        datasets: regions.map((region, i) => ({
          label: region,
          data: ['Production', 'Processing', 'Retail', 'Consumption'].map(s => regionalWaste[s][i]),
          backgroundColor: regionColors[region],
          borderRadius: 3,
          borderSkipped: false,
        }))
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            position: 'bottom',
            labels: { color: textDim, font: { family: 'JetBrains Mono', size: 9 }, boxWidth: 12, padding: 8 }
          }
        },
        scales: {
          x: { stacked: true, ticks: { color: textDim, font: { family: 'JetBrains Mono', size: 10 } }, grid: { color: gridColor } },
          y: { stacked: true, ticks: { color: textDim, font: { family: 'JetBrains Mono', size: 10 }, callback: v => v + '%' }, grid: { color: gridColor }, max: 100 }
        }
      }
    });

    // Emissions bar with Mt labels
    const emissionsMt = [1372, 990, 742, 1395];
    new Chart(document.getElementById('emissionsChart'), {
      type: 'bar',
      data: {
        labels: stages,
        datasets: [{
          label: 'Emissions (Mt CO₂e)',
          data: emissionsMt,
          backgroundColor: Object.values(stageColors),
          borderRadius: 4,
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { display: false },
          tooltip: {
            callbacks: {
              label: function(ctx) {
                const pct = [30.5, 22.0, 16.5, 31.0][ctx.dataIndex];
                return `${ctx.raw} Mt CO₂e (${pct}%)`;
              }
            }
          }
        },
        scales: {
          x: { ticks: { color: textDim, font: { family: 'JetBrains Mono', size: 11 } }, grid: { color: gridColor } },
          y: { ticks: { color: textDim, font: { family: 'JetBrains Mono', size: 11 }, callback: v => v + ' Mt' }, grid: { color: gridColor } }
        }
      }
    });

    // Avoidable waste heatmap-style
    const avoidableMatrix = [
      [55, 70, 78, 62],
      [58, 72, 80, 65],
      [75, 68, 50, 30],
      [72, 65, 52, 40],
      [68, 60, 58, 48],
      [65, 67, 64, 52]
    ];

    new Chart(document.getElementById('avoidableChart'), {
      type: 'bar',
      data: {
        labels: stages,
        datasets: regions.map((region, i) => ({
          label: region,
          data: avoidableMatrix[i],
          backgroundColor: regionColors[region],
          borderRadius: 3,
        }))
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            position: 'bottom',
            labels: { color: textDim, font: { family: 'JetBrains Mono', size: 9 }, boxWidth: 12, padding: 6 }
          }
        },
        scales: {
          x: { ticks: { color: textDim, font: { family: 'JetBrains Mono', size: 10 } }, grid: { color: gridColor } },
          y: { ticks: { color: textDim, font: { family: 'JetBrains Mono', size: 10 }, callback: v => v + '%' }, grid: { color: gridColor }, max: 100 }
        }
      }
    });
  </script>
</body>
